import React from "react";

export default function Progress() {

  const showCourses = () => {
    alert("Completed Courses : 8");
  };

  const showScore = () => {
    alert("Overall Score : 92%");
  };

  const showAttendance = () => {
    alert("Attendance : 96%");
  };

  const showSkills = () => {
    alert("Skills Learned : 15");
  };

  return (

    <div
      style={{
        minHeight: "100vh",
        background: "#f1f5f9",
        padding: "40px"
      }}
    >

      <h1
        style={{
          textAlign: "center",
          color: "#1e293b",
          marginBottom: "40px"
        }}
      >

        📈 Progress Dashboard

      </h1>

      <div

        style={{

          display: "grid",

          gridTemplateColumns:

          "repeat(auto-fit,minmax(250px,1fr))",

          gap: "25px"

        }}

      >

        <div style={blueCard}>

          <h2>📚 Courses</h2>

          <h1>8</h1>

          <p>Completed Courses</p>

          <button

            style={btn}

            onClick={showCourses}

          >

            View Details

          </button>

        </div>



        <div style={greenCard}>

          <h2>🏆 Score</h2>

          <h1>92%</h1>

          <p>Overall Performance</p>

          <button

            style={btn}

            onClick={showScore}

          >

            View Details

          </button>

        </div>



        <div style={orangeCard}>

          <h2>🔥 Attendance</h2>

          <h1>96%</h1>

          <p>Current Attendance</p>

          <button

            style={btn}

            onClick={showAttendance}

          >

            View Details

          </button>

        </div>



        <div style={pinkCard}>

          <h2>⭐ Skills</h2>

          <h1>15</h1>

          <p>Skills Learned</p>

          <button

            style={btn}

            onClick={showSkills}

          >

            View Details

          </button>

        </div>

      </div>

    </div>

  );

}

const btn = {

  background: "white",

  color: "#111",

  border: "none",

  padding: "10px 18px",

  borderRadius: "8px",

  cursor: "pointer",

  marginTop: "15px"

};

const blueCard = {

  background: "#2563eb",

  color: "white",

  padding: "30px",

  borderRadius: "20px",

  textAlign: "center"

};

const greenCard = {

  background: "#16a34a",

  color: "white",

  padding: "30px",

  borderRadius: "20px",

  textAlign: "center"

};

const orangeCard = {

  background: "#f59e0b",

  color: "white",

  padding: "30px",

  borderRadius: "20px",

  textAlign: "center"

};

const pinkCard = {

  background: "#ec4899",

  color: "white",

  padding: "30px",

  borderRadius: "20px",

  textAlign: "center"

};
